<?php
namespace App\Http\Controllers;
use App\Models\DevotionSession;use Illuminate\Http\{RedirectResponse,Request};use Illuminate\Support\Str;use Illuminate\Validation\Rule;use Inertia\{Inertia,Response};
class AttendanceController extends Controller {public function index():Response{$sessions=DevotionSession::withCount('attendanceRecords')->orderByDesc('session_date')->paginate(12);return Inertia::render('Attendance/Index',['sessions'=>$sessions]);}public function store(Request $r):RedirectResponse{$data=$r->validate(['name'=>'required|string|max:150','session_date'=>'required|date','start_time'=>'required|date_format:H:i','end_time'=>'required|date_format:H:i|after:start_time','location'=>'required|string|max:150']);DevotionSession::create([...$data,'qr_token'=>Str::random(40),'status'=>'scheduled','created_by'=>$r->user()->id]);return back()->with('success','Devotion session created.');}public function status(Request $r,DevotionSession $session):RedirectResponse{$data=$r->validate(['status'=>['required',Rule::in(['scheduled','open','closed','cancelled'])]]);$session->update($data);return back()->with('success','Session status updated.');}}
